{
  "extractions": [
    {
      "unit": "F001",
      "unit_attributes": {
        "logic_explanation": "A generator is permitted to accumulate up to 55 gallons of non-acute hazardous waste and either 1 quart of liquid acute hazardous waste or 1 kg (2.2 lbs) of solid acute hazardous waste in satellite accumulation areas without a permit or standard Chapter compliance, provided all exemption conditions are satisfied.",
        "statement": "A generator may accumulate as much as fifty-five gallons of non-acute hazardous waste and either one quart of liquid acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 of the Administrative Code or one kilogram (kg) (2.2 pounds) of solid acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 of the Administrative Code in containers at or near any point of generation where wastes initially accumulate which is under the control of the operator of the process generating the waste, without a permit or permit by rule and without complying with the requirements of Chapters 3745-50, 3745-54 to 3745-57 and 3745-205, 3745-65 to 3745-69 and 3745-256, 3745-266, and 3745-267 of the Administrative Code, provided that all of the conditions for exemption in this rule are met.",
        "kind": "permission",
        "modality": "may",
        "references": [
          "3745-51-31",
          "3745-51-33(E)",
          "3745-50",
          "3745-54",
          "3745-55",
          "3745-56",
          "3745-57",
          "3745-205",
          "3745-65",
          "3745-66",
          "3745-67",
          "3745-68",
          "3745-69",
          "3745-256",
          "3745-266",
          "3745-267"
        ]
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "logic_explanation": "A generator may comply with the conditions for exemption in this rule rather than the central accumulation area conditions in rule 3745-52-16(B) or 3745-52-17(A), except as required in paragraphs (A)(7) and (A)(8).",
        "statement": "A generator may comply with the conditions for exemption in this rule instead of complying with the conditions for exemption in paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code, except as required in paragraphs (A)(7) and (A)(8) of this rule.",
        "kind": "permission",
        "modality": "may",
        "references": [
          "3745-52-16(B)",
          "3745-52-17(A)",
          "3745-52-15(A)(7)",
          "3745-52-15(A)(8)"
        ]
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "logic_explanation": "When a container holding hazardous waste is not in good condition or begins to leak, the generator must immediately choose between transferring the waste to a compliant container or transferring/managing it in a compliant central accumulation area.",
        "statement": "As a condition for satellite accumulation exemption, if a container holding hazardous waste is not in good condition, or if the container begins to leak, the generator shall immediately transfer the hazardous waste from this container to a container that is in good condition and does not leak, or immediately transfer and manage the waste in a central accumulation area operated in compliance with paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code.",
        "kind": "requirement",
        "modality": "must",
        "references": [
          "3745-52-16(B)",
          "3745-52-17(A)"
        ]
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "As a condition for satellite accumulation exemption, the generator shall use a container made of or lined with materials that will not react with, and are otherwise compatible with, the hazardous waste to be accumulated, so that the ability of the container to contain the waste is not impaired.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "logic_explanation": "Placing incompatible wastes or materials in the same container is prohibited unless paragraph (B) of rule 3745-65-17 is complied with.",
        "statement": "As a condition for satellite accumulation exemption, incompatible wastes, or incompatible wastes and materials, (see appendix to rule 3745-66-99 of the Administrative Code for examples) shall not be placed in the same container, unless paragraph (B) of rule 3745-65-17 of the Administrative Code is complied with.",
        "kind": "prohibition",
        "modality": "must_not",
        "references": [
          "3745-66-99",
          "3745-65-17(B)"
        ]
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "logic_explanation": "Placing hazardous waste in an unwashed container that previously held incompatible waste or material is prohibited unless paragraph (B) of rule 3745-65-17 is complied with.",
        "statement": "As a condition for satellite accumulation exemption, hazardous waste shall not be placed in an unwashed container that previously held an incompatible waste or material (see appendix to rule 3745-66-99 of the Administrative Code for examples), unless paragraph (B) of rule 3745-65-17 of the Administrative Code is complied with.",
        "kind": "prohibition",
        "modality": "must_not",
        "references": [
          "3745-66-99",
          "3745-65-17(B)"
        ]
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "As a condition for satellite accumulation exemption, a container holding a hazardous waste that is incompatible with any waste or other materials accumulated nearby in other containers shall be separated from the other materials or protected from the incompatible waste or material by any practical means.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F008:F012",
      "unit_attributes": {
        "logic_explanation": "Containers must be closed at all times during accumulation, except either when handling waste (adding, removing, consolidating) or when temporary venting is necessary for equipment operation or pressure/danger prevention.",
        "statement": "As a condition for satellite accumulation exemption, a container holding hazardous waste shall be closed at all times during accumulation, except when adding, removing, or consolidating waste, or when temporary venting of a container is necessary either for the proper operation of equipment or to prevent dangerous situations, such as build-up of extreme pressure.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F013:F015",
      "unit_attributes": {
        "logic_explanation": "A generator must mark or label satellite containers with both the words 'Hazardous Waste' and an indication of the hazards of the contents.",
        "statement": "As a condition for satellite accumulation exemption, a generator shall mark or label the generator's container with both the words \"Hazardous Waste\" and an indication of the hazards of the contents (examples include, but are not limited to, the applicable hazardous waste characteristics [i.e., ignitable, corrosive, reactive, toxic]; hazard communication consistent with the department of transportation requirements at 49 CFR Part 172 subpart E [labeling] or subpart F [placarding]; a hazard statement or pictogram consistent with the occupational safety and health administration hazard communication standard at 29 CFR 1910.1200; or a chemical hazard label consistent with the national fire protection association code 704).",
        "kind": "requirement",
        "modality": "must",
        "references": [
          "49 CFR Part 172 subpart E",
          "49 CFR Part 172 subpart F",
          "29 CFR 1910.1200"
        ]
      }
    },
    {
      "unit": "F016:F021",
      "unit_attributes": {
        "logic_explanation": "When accumulating excess waste at or near a point of generation, the generator must within three consecutive calendar days either comply with central accumulation area requirements or remove the excess to one of three specified destinations.",
        "statement": "A generator who accumulates either acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 of the Administrative Code or non-acute hazardous waste in excess of the amounts listed in paragraph (A) of this rule at or near any point of generation shall, within three consecutive calendar days, do either of the following: (a) comply with the applicable central accumulation area requirements in paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code; or (b) remove the excess from the satellite accumulation area within three consecutive calendar days to either a central accumulation area operated in accordance with the applicable requirements in paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code, an on-site permit by rule or permitted treatment, storage, or disposal facility, or an off-site designated facility.",
        "kind": "requirement",
        "modality": "must",
        "references": [
          "3745-51-31",
          "3745-51-33(E)",
          "3745-52-16(B)",
          "3745-52-17(A)"
        ]
      }
    },
    {
      "unit": "F022",
      "unit_attributes": {
        "logic_explanation": "Both continuing compliance with paragraphs (A)(1) through (A)(5) and marking/labeling the containers with the date excess accumulation began are mandatory during the three-consecutive-calendar-day excess accumulation period.",
        "statement": "During the three-consecutive-calendar-day period when acute or non-acute hazardous waste accumulates in excess of the satellite limits, the generator shall continue to comply with paragraphs (A)(1) to (A)(5) of this rule and shall mark or label the containers holding the excess accumulation of hazardous waste with the date the excess amount began accumulating.",
        "kind": "requirement",
        "modality": "must",
        "references": [
          "3745-52-15(A)(1)",
          "3745-52-15(A)(2)",
          "3745-52-15(A)(3)",
          "3745-52-15(A)(4)",
          "3745-52-15(A)(5)"
        ]
      }
    },
    {
      "unit": "F023",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "All satellite accumulation areas operated by a small quantity generator shall meet the preparedness and prevention requirements of paragraph (B)(8) of rule 3745-52-16 of the Administrative Code and emergency procedures of paragraph (B)(9) of rule 3745-52-16 of the Administrative Code.",
        "kind": "requirement",
        "modality": "must",
        "references": [
          "3745-52-16(B)(8)",
          "3745-52-16(B)(9)"
        ]
      }
    },
    {
      "unit": "F024",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "All satellite accumulation areas operated by a large quantity generator shall meet the preparedness, prevention, and emergency procedures in rules 3745-52-250 to 3745-52-265 of the Administrative Code.",
        "kind": "requirement",
        "modality": "must",
        "references": [
          "3745-52-250",
          "3745-52-265"
        ]
      }
    },
    {
      "unit": "F026",
      "unit_attributes": {
        "logic_explanation": null,
        "statement": "For dates of non-regulatory government publications, publications of recognized organizations and associations, federal rules, and federal statutory provisions referenced in this rule, see rule 3745-50-11 of the Administrative Code titled \"Incorporated by reference.\"",
        "kind": "statement",
        "modality": "not_stated",
        "references": [
          "3745-50-11"
        ]
      }
    }
  ]
}
